<?php namespace App\Http\Controllers;
use App\Models\{Entry,Submission}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Mail,Log}; use Illuminate\Support\Str;
class PortalController {
 public static function active(){return Entry::where('status','published')->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->where(fn($q)=>$q->whereNull('deadline')->orWhere('deadline','>',now()))->where(fn($q)=>$q->whereNull('event_start')->orWhere('event_start','>',now()));}
 public function index(Request $r,string $type){abort_unless(array_key_exists($type,config('obm.types')),404);$q=$this->active()->where('type',$type);$r->validate(['q'=>'nullable|string|max:100','country'=>'nullable|string|max:100']);if($r->filled('q')){$s=mb_substr((string)$r->input('q'),0,100);$q->where(fn($a)=>$a->where('title','like','%'.$s.'%')->orWhere('title_bn','like','%'.$s.'%')->orWhere('summary','like','%'.$s.'%'));}if($r->filled('country'))$q->where('country',mb_substr((string)$r->input('country'),0,100));return view('entries',['type'=>$type,'entries'=>$q->latest()->paginate(24)->withQueryString(),'countries'=>$this->active()->where('type',$type)->whereNotNull('country')->distinct()->orderBy('country')->pluck('country')]);}
 public function show(string $slug){return view('entry',['entry'=>$this->active()->where('slug',$slug)->firstOrFail()]);}
 public function legacy(string $page='index'){abort_unless(preg_match('/^[a-z0-9-]+$/D',$page),404);$file=resource_path('views/legacy/'.$page.'.html');abort_unless(is_file($file),404);$html=file_get_contents($file);$html=str_replace('https://www.onlinebanglamedia.com',rtrim(config('app.url'),'/'),$html);$links='<div class="container" style="padding:12px;display:flex;gap:18px;flex-wrap:wrap"><a href="/opportunities/job">Live jobs</a><a href="/opportunities/scholarship">Scholarships</a><a href="/opportunities/event">Community events</a><a href="/opportunities/news">News feeds</a><a href="/opportunities/directory">Dynamic directory</a><a href="/submit">Submit listing</a></div>'; $html=preg_replace('/<body[^>]*>/i','$0'.$links,$html,1);if($page==='index'){$html=preg_replace('/<main\b[^>]*>/i','$0'.view('ad-slot',['slot'=>'home_top'])->render(),$html,1);$html=str_replace('</main>',view('promotion')->render().view('ad-slot',['slot'=>'home_bottom'])->render().'</main>',$html);}elseif(in_array($page,['news-media','education','jobs','business','travel','categories','community','abroad'])){$html=str_replace('</main>',view('ad-slot',['slot'=>'category_bottom'])->render().'</main>',$html);}return response($html);}
 public function submit(Request $r){abort_if($r->filled('company_fax'),422);$data=$r->validate(['name'=>'required|string|max:150','email'=>'required|email:rfc|max:254','type'=>'required|in:new,correction,broken,job,scholarship,event,general','listing'=>'required|string|max:200','category'=>'nullable|string|max:100','region'=>'nullable|string|max:100','website'=>'nullable|url:http,https|max:2048','message'=>'required|string|max:4000','consent'=>'accepted']);unset($data['consent']);$s=Submission::create($data+['reference'=>strtoupper(Str::random(12)),'consented_at'=>now()]);try{Mail::raw("Reference: {$s->reference}\n".json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),fn($m)=>$m->to(config('obm.recipient'))->replyTo($s->email)->subject('OBM submission '.$s->reference));$s->update(['emailed_at'=>now()]);}catch(\Throwable $e){Log::warning('Submission email failed',['id'=>$s->id]);}return back()->with('success','Submission saved for review. Reference: '.$s->reference);}
 public function sitemap(){ $urls=[url('/'),url('/submit')];foreach(glob(resource_path('views/legacy/*.html')) as $p){$n=basename($p);if(!str_starts_with($n,'profile-')&&!in_array($n,['index.html','listing.html','submit.html','directory.html']))$urls[]=url('/'.$n);}foreach(config('obm.types') as $t=>$label)if($this->active()->where('type',$t)->exists())$urls[]=url('/opportunities/'.$t);$urls[]=url('/scholarship-sources');foreach($this->active()->where(fn($q)=>$q->where('type','!=','directory')->orWhereNotNull('verified_at'))->select('slug')->cursor() as $e)$urls[]=url('/entry/'.$e->slug);$xml='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($urls as $u)$xml.='<url><loc>'.htmlspecialchars($u,ENT_XML1).'</loc></url>';return response($xml.'</urlset>',200,['Content-Type'=>'application/xml']);}
}
